/**
 * Extract the task/session name from a terminal window title set by an agent TUI.
 *
 * - claude: Claude Code sets the title to `<spinner glyph> <topic>` (e.g. `✳ Terminal blind overlay`,
 *   `⠂ Terminal blind overlay`). The idle/default title is `✳ Claude Code`, which is not a task.
 * - pi: pi sets the title to `<app> - <session name> - <folder>` (e.g. `π - fix login - dashboard`,
 *   `Pi-Bolt - a - b - dashboard`). The session name is everything between the first and last ` - `
 *   separators, so it may itself contain ` - `. With fewer than three segments there is no session name.
 *
 * Returns `null` when the title carries no task/session name.
 */
export function taskTitle(kind: string, title: string): string | null {
	const trimmed = title.trim();
	if (!trimmed) return null;

	if (kind === "claude") {
		// Strip a single leading spinner/symbol glyph followed by whitespace.
		const topic = trimmed.replace(/^[^\p{L}\p{N}]\s+/, "").trim();
		if (!topic || topic === "Claude Code") return null;
		return topic;
	}

	if (kind === "pi") {
		const parts = trimmed.split(" - ");
		if (parts.length < 3) return null;
		const session = parts.slice(1, -1).join(" - ").trim();
		return session ? session : null;
	}

	return null;
}
